// ÜRETİLDİ — elle düzenlemeyin. Kaynak: tamga-network/examples (npm run examples:sync)
export const EXAMPLES = {
  webLoginServer: "/**\n * Example 01 — \"Sign up / Sign in with TamgaID\" on your website, using the hosted verifier.\n *\n * Your SERVER opens each presentation, proving who it is with a short-lived assertion signed by the key of\n * your trust-list registration (ADR-0017). The page only shows the QR code and polls a status token; the\n * values the person approved are handed to your server once.\n *\n *   npm install @tamga-network/verifier\n */\nimport { createHmac } from \"node:crypto\";\nimport { createRpAssertion, type RpSigner } from \"@tamga-network/verifier\";\n\nexport interface SignInConfig {\n  /** The hosted verifier, e.g. \"https://verify.tamga.network\". */\n  verifier: string;\n  /** Your registration: pemRpSigner(KEY_PEM, CERT_PEM, \"x509_san_dns:example.com\"). */\n  rp: RpSigner;\n  /** Your own secret; account keys are derived from it (never store the raw document value). */\n  siteSecret: string;\n  fetch?: typeof fetch;\n}\n\n/** What your page needs to draw the QR code and poll the status. */\nexport interface StartedPresentation {\n  presentation_id: string;\n  qr_payload: string;\n  expires_at: string;\n  status_token: string;\n}\n\nexport type SignInResult =\n  | { ok: true; accountKey: string; givenName?: string; familyName?: string }\n  | { ok: false; outcome: \"PENDING\" | \"REJECTED\" | \"INDETERMINATE\" | \"ALREADY_USED\" };\n\nexport function tamgaSignIn(cfg: SignInConfig) {\n  const f = cfg.fetch ?? fetch;\n  const auth = async () => ({ authorization: `Bearer ${await createRpAssertion(cfg.rp, cfg.verifier)}` });\n\n  /** POST /tamga/start → return this JSON to your page (TamgaVerifier.mount({ start })). */\n  async function start(policy: \"site-uyelik\" | \"site-giris\"): Promise<StartedPresentation> {\n    const r = await f(`${cfg.verifier}/presentations`, {\n      method: \"POST\",\n      headers: { ...(await auth()), \"content-type\": \"application/json\", accept: \"application/json\" },\n      body: JSON.stringify({ policy_id: policy }),\n    });\n    if (!r.ok) throw new Error(`verifier refused the request (${r.status})`);\n    return (await r.json()) as StartedPresentation;\n  }\n\n  /** POST /tamga/session → your page sends the presentation id after ACCEPTED; decide here, on the server. */\n  async function finish(presentationId: string): Promise<SignInResult> {\n    const id = encodeURIComponent(presentationId);\n    const result = (await (await f(`${cfg.verifier}/presentations/${id}`, { headers: await auth() })).json()) as {\n      outcome?: \"ACCEPTED\" | \"REJECTED\" | \"INDETERMINATE\";\n    };\n    if (result.outcome !== \"ACCEPTED\") return { ok: false, outcome: result.outcome ?? \"PENDING\" };\n\n    const r = await f(`${cfg.verifier}/presentations/${id}/claims`, { headers: await auth() });\n    if (r.status === 410) return { ok: false, outcome: \"ALREADY_USED\" }; // values are handed out once\n    const { claims } = (await r.json()) as { claims: Record<string, unknown> };\n\n    // Keep your own keyed hash as the account key; the raw value is the same for every site.\n    const accountKey = createHmac(\"sha256\", cfg.siteSecret)\n      .update(String(claims.document_number_hash))\n      .digest(\"base64url\");\n    return {\n      ok: true,\n      accountKey,\n      givenName: claims.given_name as string | undefined,\n      familyName: claims.family_name as string | undefined,\n    };\n  }\n\n  return { start, finish };\n}",
  webLoginPage: "<!-- Example 01 — the page. The kit draws the QR code (or \"Open in Tamga Wallet\" on a phone) and polls\n     a status token. It never sees the person's data and never decides: your server does (server.ts). -->\n<script src=\"https://verify.tamga.network/tamga-verifier.js\"></script>\n<div id=\"tamga\"></div>\n<script>\n  const post = (url, body) =>\n    fetch(url, { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify(body) });\n\n  TamgaVerifier.mount(document.getElementById(\"tamga\"), {\n    verifier: \"https://verify.tamga.network\",\n    policy: \"site-uyelik\", // sign-in for an existing account: \"site-giris\"\n    start: () => post(\"/tamga/start\", { policy: \"site-uyelik\" }).then((r) => r.json()),\n    onResult: (presentationId) =>\n      post(\"/tamga/session\", { presentation_id: presentationId }).then(() => location.reload()),\n    onError: (e) => console.warn(\"Tamga:\", e),\n  });\n</script>",
  verifyOwnServer: "/**\n * Example 02 — verify documents on your own server (hiring, campus, age checks), without the hosted verifier.\n *\n * 1. Load the signed trust lists (who may issue what) and pre-fetch the revocation lists.\n * 2. Create a signed OpenID4VP request → show it as a QR code.\n * 3. The wallet posts an encrypted answer → decrypt it → run the canonical checks (T0 + A–E).\n * Three outcomes: ACCEPTED, REJECTED (with the failing step) or INDETERMINATE (\"could not check right now\").\n *\n *   npm install @tamga-network/verifier @tamga-network/trust @tamga-network/core\n */\nimport { pemToDer } from \"@tamga-network/core\";\nimport { fetchListTrustSource, verifyJws } from \"@tamga-network/trust\";\nimport {\n  createPresentationRequest,\n  dcqlFromPolicy,\n  decryptResponse,\n  PrefetchStatusCache,\n  verifyPresentation,\n  type Policy,\n  type PresentationRequest,\n  type RpSigner,\n} from \"@tamga-network/verifier\";\n\n/** A hiring policy: a bachelor's diploma, four fields, nothing else. */\nexport const DIPLOMA_POLICY: Policy = {\n  policy_id: \"hiring-bachelor\",\n  purpose: { \"en-GB\": \"Confirm graduation for a job application\" },\n  credentials: [\n    {\n      id: \"diploma\",\n      vct_values: [\"urn:tamga:edu:DiplomaCredential:1\"],\n      required_claims: [\"is_graduate\", \"qualification_title\", \"eqf_level\", \"awarding_body_name\"],\n      constraints: { is_graduate: true, eqf_level: { min: 6 } },\n    },\n  ],\n  trust: { min_issuer_assurance: \"I2\", allowed_categories: [\"EDUCATION\"], require_recognition: true, state_code: \"TR\" },\n  freshness: { max_status_token_age_sec: 7200, max_trust_age_sec: 86400 },\n};\n\nexport interface OwnVerifierConfig {\n  /** Where the trust lists are published, e.g. \"https://trust.tamga.network\". */\n  trustBase: string;\n  /** Root fingerprints, fixed in your configuration (published at tamga.network/trust-anchor). */\n  rootFingerprints: string[];\n  /** Your registration: pemRpSigner(KEY_PEM, CERT_PEM, \"x509_san_dns:example.com\"). */\n  signer: RpSigner;\n  /** Your public base URL; the wallet fetches /vp/req/:id and posts to /vp/response here. */\n  publicBase: string;\n  fetch?: typeof fetch;\n  /** Revocation-list fetcher (defaults to fetch with a timeout). */\n  fetchStatus?: (url: string) => Promise<string | null>;\n  anchorMaxAgeMs?: number;\n}\n\nexport async function createOwnVerifier(cfg: OwnVerifierConfig) {\n  const f = cfg.fetch ?? fetch;\n  const http = async (url: string) => {\n    const r = await f(url);\n    return { status: r.status, text: () => r.text() };\n  };\n  // 1) Trust lists, verified against your fixed root fingerprints; anchors included (revocation checks need them).\n  const { source: trust, store } = await fetchListTrustSource(cfg.trustBase, http, {\n    rootFingerprints: cfg.rootFingerprints,\n    verifyJws,\n    anchors: true,\n    anchorMaxAgeMs: cfg.anchorMaxAgeMs,\n  });\n  const rootCertsDer = [...store.root_cas.values()].flatMap((ca) => (ca.cert_pem ? [pemToDer(ca.cert_pem)] : []));\n  // Pre-fetch every anchored revocation list: no network call at verification time.\n  const statusCache = new PrefetchStatusCache(cfg.fetchStatus);\n  await statusCache.refresh([...store.status_anchors.values()].map((a) => a.list_uri));\n\n  const pending = new Map<string, { req: PresentationRequest; policy: Policy }>();\n\n  /** 2) Start: returns the QR payload. Serve `requestObject(id)` at GET /vp/req/:id. */\n  async function start(policy: Policy = DIPLOMA_POLICY) {\n    const req = await createPresentationRequest({\n      signer: cfg.signer,\n      dcql: dcqlFromPolicy(policy),\n      responseUri: `${cfg.publicBase}/vp/response`,\n      requestUriBase: `${cfg.publicBase}/vp/req`,\n      purpose: Object.values(policy.purpose)[0],\n    });\n    pending.set(req.presentationId, { req, policy });\n    return { presentationId: req.presentationId, qrPayload: req.qrPayload };\n  }\n\n  /** GET /vp/req/:id → body with content-type application/oauth-authz-req+jwt. */\n  const requestObject = (id: string) => pending.get(id)?.req.requestJwt ?? null;\n\n  /** 3) POST /vp/response (form field `response`) → verify. Each request answers once. */\n  async function handleResponse(jwe: string) {\n    const kid = JSON.parse(Buffer.from(jwe.split(\".\")[0], \"base64url\").toString(\"utf8\")).kid as string;\n    const entry = pending.get(String(kid).replace(/^enc-/, \"\"));\n    if (!entry) throw new Error(\"unknown or already answered request\");\n    pending.delete(entry.req.presentationId);\n    const answer = await decryptResponse(jwe, entry.req.encPrivateKey);\n    if (answer.state !== entry.req.state) throw new Error(\"state mismatch\");\n    const pc = entry.policy.credentials[0];\n    return verifyPresentation({\n      presentation: answer.vp_token[pc.id][0],\n      aud: cfg.signer.clientId,\n      nonce: entry.req.nonce,\n      policy: entry.policy,\n      policyCredentialId: pc.id,\n      trust,\n      statusCache,\n      rootCertsDer,\n      rp: trust.relyingParty(cfg.signer.clientId),\n    }); // → { result: { outcome, failed_step, … }, claims } — store names, never values, in your logs\n  }\n\n  /** Refresh revocation lists on a timer (e.g. every few minutes). */\n  const refreshStatus = () => statusCache.refresh([...store.status_anchors.values()].map((a) => a.list_uri));\n\n  return { start, requestObject, handleResponse, refreshStatus, trust, statusCache };\n}",
  issueHosted: "/**\n * Example 03 — issue documents from your own system, using Tamga's hosted issuing service.\n *\n * Your institution gets a scoped API key from the Tamga operator (ADR-0016). Your server calls the service;\n * the person scans the returned link as a QR code and types the PIN you show them separately.\n *\n *   npm install @tamga-network/issuer\n */\nimport { createIssuerClient, IssuerClientError } from \"@tamga-network/issuer/client\";\n\nexport function institution(cfg: { apiKey: string; slug: string; baseUrl?: string; fetch?: typeof fetch }) {\n  const tamga = createIssuerClient({\n    baseUrl: cfg.baseUrl ?? \"https://issuer.tamga.network\",\n    slug: cfg.slug,\n    apiKey: cfg.apiKey, // tmg_<slug>_… — server side only\n    fetch: cfg.fetch,\n  });\n\n  return {\n    /** A university: offer a diploma to a graduate in your records (your own student number). */\n    async offerDiploma(studentNo: string) {\n      const offer = await tamga.createOffer({ subjectId: studentNo, vct: \"urn:tamga:edu:DiplomaCredential:1\" });\n      // offer.deepLink → show as a QR code or an \"Add to wallet\" link.\n      // offer.txCode   → show on a DIFFERENT channel than the link (screen, SMS, e-mail): never inside the QR.\n      return offer;\n    },\n\n    /** A ticket seller: sell a ticket straight into the buyer's wallet (the ticket carries no personal data). */\n    async sellTicket(eventId: string, ticketClass: string) {\n      const sale = await tamga.sellTicket({ eventId, ticketClass });\n      return { ticketId: sale.ticketId, qr: sale.offer.deepLink, pin: sale.offer.txCode };\n    },\n\n    /** Revoke (final) or suspend (reversible); verifiers see it at the next fixed publication. */\n    async cancel(credentialId: string, reason: string) {\n      try {\n        return await tamga.revoke(credentialId, reason);\n      } catch (e) {\n        if (e instanceof IssuerClientError && e.status === 404) return null; // unknown credential\n        throw e;\n      }\n    },\n  };\n}",
  checkInstitution: "/**\n * Example 04 — ask the trust lists: is this institution registered, active, and authorized for this document?\n * Useful for a directory page, an onboarding screen or a back-office check. No personal data involved.\n *\n *   npm install @tamga-network/trust\n */\nimport { fetchListTrustSource, verifyJws } from \"@tamga-network/trust\";\n\nexport async function institutionStatus(\n  trustBase: string,\n  rootFingerprints: string[],\n  slug: string,\n  vct: string,\n  opts: { fetch?: typeof fetch; anchorMaxAgeMs?: number } = {},\n) {\n  const f = opts.fetch ?? fetch;\n  const { source } = await fetchListTrustSource(\n    trustBase,\n    async (url) => {\n      const r = await f(url);\n      return { status: r.status, text: () => r.text() };\n    },\n    { rootFingerprints, verifyJws },\n  );\n  const issuer = source.issuers().find((i) => i.slug === slug);\n  if (!issuer) return { registered: false as const };\n  const now = Date.now();\n  const authorized = issuer.schema_authorizations.some(\n    (a) =>\n      a.vct === vct &&\n      a.allowed &&\n      new Date(a.valid_from).getTime() <= now &&\n      (!a.valid_until || now < new Date(a.valid_until).getTime()),\n  );\n  return {\n    registered: true as const,\n    name: issuer.legal_name,\n    category: issuer.category,\n    status: issuer.status, // ACTIVE | SUSPENDED | REVOKED | RETIRED\n    authorized,\n  };\n}",
} as const;
